package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Element_nextElementSibling_TriageGen0Test {

    @Test
    public void test_nextElementSibling_NoSiblings() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "", new Attributes());
        element.parent().children().add(new TextNode("Text"));

        // Act
        Element result = element.nextElementSibling();

        // Assert
        assertNull(result);
    }

    @Test
    public void test_nextElementSibling_SingleSibling() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "", new Attributes());
        element.parent().children().add(new TextNode("Text"));
        element.parent().children().add(new Element(Tag.valueOf("span"), "", new Attributes()));

        // Act
        Element result = element.nextElementSibling();

        // Assert
        assertEquals("span", result.tagName());
    }

    @Test
    public void test_nextElementSibling_MultipleSiblings() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "", new Attributes());
        element.parent().children().add(new TextNode("Text"));
        element.parent().children().add(new Element(Tag.valueOf("span"), "", new Attributes()));
        element.parent().children().add(new Element(Tag.valueOf("p"), "", new Attributes()));

        // Act
        Element result = element.nextElementSibling();

        // Assert
        assertEquals("p", result.tagName());
    }

    @Test
    public void test_nextElementSibling_NullParent() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "", new Attributes());
        element.parent() = null;

        // Act and Assert
        assertNull(element.nextElementSibling());
    }

    @Test
    public void test_nextElementSibling_NullSiblings() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "", new Attributes());
        element.parent().children().clear();
        element.parent().children().add(null);

        // Act and Assert
        assertNull(element.nextElementSibling());
    }
}
